mapper.select:
SELECT d.id, d.full_name, d.address, d.phone, d.note, d.file_id, f.path AS image_url, d.status, d.created_at FROM design_submissions d LEFT JOIN files f ON f.id = d.file_id
d.deleted_at IS NULL AND status = #{status}
AND (d.full_name ILIKE CONCAT('%', #{keyword}, '%') OR d.phone ILIKE CONCAT('%', #{keyword}, '%'))
ORDER BY d.created_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE design_submissions
SET deleted_at = now(), file_id = NULL, updated_by = #{updatedBy}
WHERE id = #{id}
